<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Clerk'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$book=filter_var($_POST['book_id']??null,FILTER_VALIDATE_INT);$student=filter_var($_POST['student_id']??null,FILTER_VALIDATE_INT);$due=trim((string)($_POST['due_on']??''));$notes=trim((string)($_POST['notes']??''));$today=date('Y-m-d');$d=DateTimeImmutable::createFromFormat('!Y-m-d',$due);$errs=DateTimeImmutable::getLastErrors();
if(!$book||!$student||$due===''||$d===false||$d->format('Y-m-d')!==$due||($errs!==false&&($errs['warning_count']||$errs['error_count']))||$due<$today||strlen($notes)>255){$_SESSION['error']='Choose a learner, an available book, a valid due date today or later, and notes within 255 characters.';header('Location: ../?page=library');exit;}
$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,total_copies,active FROM library_books WHERE id=:id FOR UPDATE');$q->execute(['id'=>$book]);$bookRow=$q->fetch();if(!$bookRow||!(int)$bookRow['active'])throw new DomainException('This book is unavailable for issue.');$q=$pdo->prepare("SELECT id FROM students WHERE id=:id AND status='Active' FOR UPDATE");$q->execute(['id'=>$student]);if(!$q->fetch())throw new DomainException('Only active learners can borrow library books.');$q=$pdo->prepare('SELECT COUNT(*) FROM library_loans WHERE book_id=:book AND returned_on IS NULL');$q->execute(['book'=>$book]);if((int)$q->fetchColumn()>=(int)$bookRow['total_copies'])throw new DomainException('All copies of this book are currently on loan.');$q=$pdo->prepare('INSERT INTO library_loans(book_id,student_id,issued_on,due_on,issued_by,notes) VALUES(:book,:student,:issued,:due,:user,:notes)');$q->execute(['book'=>$book,'student'=>$student,'issued'=>$today,'due'=>$due,'user'=>$user['id'],'notes'=>$notes?:null]);$loanId=(int)$pdo->lastInsertId();audit_log('library.book_issued','library_loans',$loanId,['book_id'=>$book,'student_id'=>$student,'due_on'=>$due]);$pdo->commit();$_SESSION['notice']='Book issued. The due date has been recorded.';}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Library issue failed: '.$e->getMessage());$_SESSION['error']='Could not issue the book. No loan was recorded.';}header('Location: ../?page=library');exit;
